"""Versioned updates safely adopting existing prototype databases."""import secretsimport timedef migrate_foundation(c):    c.execute(        "CREATE TABLE IF NOT EXISTS schema_versions(version INTEGER PRIMARY KEY,description TEXT NOT NULL,applied REAL NOT NULL)"    )    c.execute(        "CREATE TABLE IF NOT EXISTS revoked_tokens(jti TEXT PRIMARY KEY,user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,expires REAL NOT NULL)"    )    c.execute(        "CREATE TABLE IF NOT EXISTS clinician_profiles(user_id INTEGER REFERENCES users(id) ON DELETE CASCADE,doctor_id INTEGER REFERENCES doctors(id),PRIMARY KEY(user_id,doctor_id))"    )    if "clinician_id" not in {r["name"] for r in c.execute("PRAGMA table_info(cases)")}:        c.execute(            "ALTER TABLE cases ADD COLUMN clinician_id INTEGER REFERENCES users(id) ON DELETE SET NULL"        )    c.execute(        "CREATE TRIGGER IF NOT EXISTS assign_default_clinician AFTER INSERT ON cases WHEN NEW.clinician_id IS NULL BEGIN UPDATE cases SET clinician_id=(SELECT id FROM users WHERE email='doctor@demo.local') WHERE id=NEW.id; END"    )    c.execute(        "INSERT OR IGNORE INTO schema_versions VALUES(1,?,?)",        (            "Adopt v0.2 database; scoped clinician identities and token revocation",            time.time(),        ),    )    c.execute("DELETE FROM revoked_tokens WHERE expires<?", (time.time(),))def seed_clinicians(c, hasher):    if not c.execute("SELECT id FROM users WHERE email='cardio@demo.local'").fetchone():        c.execute(            "INSERT INTO users(email,name,role,password,consent,session_key) VALUES('cardio@demo.local','Dr. Arjun Rao','doctor',?,1,?)",            (hasher.hash("Demo@12345"), secrets.token_hex(16)),        )    gp = c.execute("SELECT id FROM users WHERE email='doctor@demo.local'").fetchone()[        "id"    ]    cardio = c.execute(        "SELECT id FROM users WHERE email='cardio@demo.local'"    ).fetchone()["id"]    for row in c.execute("SELECT id,specialty FROM doctors").fetchall():        owner = cardio if row["specialty"] == "Cardiology" else gp        c.execute(            "INSERT OR IGNORE INTO clinician_profiles VALUES(?,?)", (owner, row["id"])        )    c.execute("UPDATE cases SET clinician_id=? WHERE clinician_id IS NULL", (gp,))